#!/usr/bin/env python3
"""Regenerate the "Top Repositories" section of the profile README.

Fetches the owner's public repositories from the GitHub API, ranks them by
stars (ties broken by forks, then most recent push), and rewrites the block
between the REPOS:START / REPOS:END markers in README.md.

Environment variables:
  GITHUB_USER   GitHub username              (default: collabray)
  GITHUB_TOKEN  Token for higher rate limits (optional, provided in Actions)
  TOP_N         Number of repos to show      (default: 6)
  MIN_STARS     Minimum stars to qualify     (default: 0)
  README_PATH   Path to the README           (default: README.md)
"""
import json
import os
import re
import sys
import urllib.request

USER = os.environ.get("GITHUB_USER", "collabray")
TOKEN = os.environ.get("GITHUB_TOKEN")
TOP_N = int(os.environ.get("TOP_N", "6"))
MIN_STARS = int(os.environ.get("MIN_STARS", "0"))
README = os.environ.get("README_PATH", "README.md")
START, END = "<!-- REPOS:START -->", "<!-- REPOS:END -->"


def fetch_repos():
    repos, page = [], 1
    while True:
        url = (f"https://api.github.com/users/{USER}/repos"
               f"?type=owner&per_page=100&page={page}")
        req = urllib.request.Request(url, headers={
            "Accept": "application/vnd.github+json",
            "User-Agent": "profile-readme-updater",
            **({"Authorization": f"Bearer {TOKEN}"} if TOKEN else {}),
        })
        with urllib.request.urlopen(req, timeout=30) as resp:
            batch = json.load(resp)
        if not batch:
            return repos
        repos.extend(batch)
        page += 1


def select(repos):
    eligible = [
        r for r in repos
        if not r["fork"]
        and not r["archived"]
        and r["name"].lower() != USER.lower()      # skip the profile repo
        and r["stargazers_count"] >= MIN_STARS
    ]
    eligible.sort(key=lambda r: (r["stargazers_count"], r["forks_count"], r["pushed_at"]),
                  reverse=True)
    return eligible[:TOP_N]


def esc(text):
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def render(repos):
    if not repos:
        return "_No public repositories to display yet._"
    lines = ["| Repository | Description | Language | Stars | Forks |",
             "|---|---|---|---:|---:|"]
    for r in repos:
        lines.append(
            f"| [{r['name']}]({r['html_url']}) "
            f"| {esc(r['description']) or '—'} "
            f"| {r['language'] or '—'} "
            f"| {r['stargazers_count']} "
            f"| {r['forks_count']} |"
        )
    return "\n".join(lines)


def main():
    with open(README, encoding="utf-8") as f:
        content = f.read()
    pattern = re.compile(re.escape(START) + r".*?" + re.escape(END), re.S)
    if not pattern.search(content):
        sys.exit(f"Markers {START} / {END} not found in {README}")
    block = (f"{START}\n<!-- Generated by scripts/update_repos.py. Do not edit by hand. -->\n\n"
             f"{render(select(fetch_repos()))}\n\n{END}")
    new = pattern.sub(lambda _: block, content)
    if new != content:
        with open(README, "w", encoding="utf-8") as f:
            f.write(new)
        print("README updated.")
    else:
        print("No changes.")


if __name__ == "__main__":
    main()
